(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-115":{scenario:{company:"Azure Harbor Engineering",supervisor:{name:"Vũ Hoàng Lan",role:{vi:"Giám đốc Tài chính",en:"Chief Financial Officer"}},ref_code:"FS-2512",title:{vi:"Chữ ký kế toán trưởng là cam kết trung thực.",en:"A chief accountant's signature is a pledge of truth."},brief:{vi:"Báo cáo tài chính năm 2025 (FS-2512) chưa phát hành. Ngày 20/01/2026, tòa án ra quyết định mở thủ tục phá sản đối với khách hàng Kestrel Steel Works; khoản phải thu 1.450 triệu đồng phát sinh tháng 11/2025, chưa đến hạn nên chưa trích dự phòng. Quản tài viên ước tính chỉ thu hồi được 20%. Lợi nhuận trước thuế trên bản nháp là 5.800 triệu đồng. Sửa cách xử lý sự kiện theo VAS 23 và lợi nhuận trước thuế sau điều chỉnh, rồi lập tờ trình ký báo cáo.",en:"The 2025 financial statements (FS-2512) have not been issued. On 20 Jan 2026 a court opened bankruptcy proceedings against customer Kestrel Steel Works; the VND 1,450 million receivable arose in Nov 2025 and was not yet due, so no provision was made. The administrator expects to recover only 20%. Draft profit before tax is VND 5,800 million. Correct the VAS 23 treatment and the adjusted profit before tax, then write the sign-off memo."},reference_title:{vi:"Hồ sơ sự kiện sau ngày khóa sổ & đánh giá nợ · FS-2512",en:"Subsequent events & receivable assessment file · FS-2512"},fields:[{id:"EVENT_TYPE",label:{vi:"Xử lý sự kiện sau ngày kết thúc kỳ kế toán năm",en:"Treatment of the subsequent event"},initial:"DISCLOSE-ONLY",expected:"ADJUSTING",choices:["ADJUSTING","DISCLOSE-ONLY","IGNORE"],reference:"Hồ sơ sự kiện sau ngày khóa sổ - VAS 23",hint:{vi:"Hỏi: sự kiện này cung cấp thêm bằng chứng về tình trạng đã tồn tại tại ngày 31/12/2025 hay phát sinh hoàn toàn mới sau đó?",en:"Ask: does the event give more evidence about a condition that existed at 31 Dec 2025, or is it entirely new?"}},{id:"PBT_ADJ",label:{vi:"Lợi nhuận trước thuế sau điều chỉnh (VND)",en:"Adjusted profit before tax (VND)"},initial:"5800000000",expected:"4640000000",reference:"Biên bản đánh giá nợ phải thu",ref_value:{vi:"Phải thu Kestrel 1.450.000.000 đồng; dự kiến thu hồi 20%; LNTT nháp 5.800.000.000 đồng",en:"Kestrel receivable VND 1,450,000,000; expected recovery 20%; draft PBT VND 5,800,000,000"},hint:{vi:"Dự phòng bằng phần dự kiến không thu hồi được; khoản dự phòng làm tăng chi phí và giảm lợi nhuận trước thuế.",en:"The provision equals the part not expected to be recovered; it adds expense and reduces profit before tax."}}],sop32:{vi:"Với khách nợ đã mở thủ tục phá sản, dự phòng = nợ phải thu x (100% - tỷ lệ thu hồi ước tính); lợi nhuận trước thuế sau điều chỉnh = LNTT nháp - dự phòng bổ sung.",en:"For a debtor in bankruptcy proceedings, provision = receivable x (100% - estimated recovery rate); adjusted profit before tax = draft PBT - additional provision."},context:{label:"BCTC NHÁP 2025 / FS-2512",metrics:[{label:{vi:"LNTT bản nháp",en:"Draft PBT"},value:"5,800,000,000 VND"},{label:{vi:"Phải thu Kestrel",en:"Kestrel receivable"},value:"1,450,000,000 VND"},{label:{vi:"Tỷ lệ thu hồi ước tính",en:"Estimated recovery"},value:"20%"}]},crisis:{vi:"Tổng giám đốc nói: “Đừng điều chỉnh, ghi một dòng thuyết minh là đủ. Lợi nhuận phải giữ 5,8 tỷ để kịp hồ sơ vay vốn tuần sau. Kế toán trưởng cứ ký, có gì tôi chịu trách nhiệm.”",en:"The CEO says: “Do not adjust, one line in the notes is enough. Profit must stay at 5.8 billion for next week's loan file. Just sign it, I will take responsibility.”"},options:{safe:{vi:"Từ chối ký báo cáo chưa điều chỉnh, giải trình bằng văn bản theo VAS 23 và quy định trích lập dự phòng, báo chủ sở hữu hoặc Hội đồng quản trị và trao đổi với kiểm toán viên độc lập.",en:"Refuse to sign unadjusted statements, explain in writing under VAS 23 and provisioning rules, report to the owner or the Board and discuss with the external auditor."},shortcut:{vi:"Ký báo cáo như bản nháp vì tổng giám đốc đã nhận trách nhiệm, năm sau trích bù.",en:"Sign the draft because the CEO accepted responsibility and catch up the provision next year."},wait:{vi:"Không ký, không giải trình, để kiểm toán viên và tổng giám đốc tự giải quyết.",en:"Neither sign nor explain, and let the auditor and the CEO settle it."}},questions:{vi:["Vì sao quyết định mở thủ tục phá sản ngày 20/01/2026 là sự kiện cần điều chỉnh BCTC năm 2025? Trình bày cách bạn tính lại lợi nhuận trước thuế.","Kế toán trưởng có quyền và trách nhiệm gì khi bị yêu cầu ký báo cáo tài chính chưa trung thực? Bạn báo cáo cho ai?"],en:["Why is the bankruptcy decision of 20 Jan 2026 an adjusting event for the 2025 statements? Show how you recalculated profit before tax.","What rights and duties does a chief accountant have when asked to sign misleading statements? To whom do you report?"]},hints:{vi:["Đặt ngày xảy ra sự kiện cạnh ngày kết thúc kỳ và ngày phát hành báo cáo để xác định phạm vi VAS 23.","Tính phần nợ dự kiến không thu hồi trước khi trừ vào lợi nhuận ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không ký báo cáo sai lệch trọng yếu dù có cam kết miệng của lãnh đạo."],en:["Place the event date next to the year-end and issue dates to define the VAS 23 window.","Work out the unrecoverable amount before deducting it from profit in SOP 3.2.","Re-read SOP 4.2: never sign materially misstated statements, even with a verbal promise from management."]}},learning:{summary:{vi:"Kế toán trưởng tổ chức bộ máy và công tác kế toán, ban hành chính sách kế toán, kiểm soát thu chi, thuế, tài sản và chịu trách nhiệm về tính trung thực, hợp lý của báo cáo tài chính. Đây là người làm việc trực tiếp với kiểm toán, ngân hàng, cơ quan thuế và tham mưu tài chính cho ban lãnh đạo. Nghề đòi hỏi chứng chỉ kế toán trưởng, hiểu sâu chuẩn mực và pháp luật, năng lực quản lý đội ngũ và bản lĩnh độc lập chuyên môn.",en:"A chief accountant organizes the accounting function, sets accounting policies, controls receipts and payments, taxes and assets, and is responsible for the truth and fairness of the financial statements. The role works directly with auditors, banks and the tax authority and advises management on finance. It requires the chief accountant certificate, deep knowledge of standards and law, team leadership and the courage to stay professionally independent."},responsibilities:{vi:["Tổ chức bộ máy kế toán, phân công nhiệm vụ và kiểm soát chất lượng số liệu.","Ban hành, cập nhật chính sách kế toán và quy chế tài chính nội bộ.","Rà soát, ký báo cáo tài chính, báo cáo thuế và chịu trách nhiệm về tính trung thực.","Làm việc với kiểm toán độc lập, ngân hàng và cơ quan thuế, xử lý các vấn đề trọng yếu.","Tham mưu ban lãnh đạo về dòng tiền, vốn vay, rủi ro tài chính và tuân thủ."],en:["Organize the accounting team, assign duties and control data quality.","Issue and update accounting policies and internal financial rules.","Review and sign financial and tax reports and answer for their truthfulness.","Work with external auditors, banks and the tax authority on material issues.","Advise management on cash flow, borrowing, financial risk and compliance."]},competencies:[{name:{vi:"Chuẩn mực & chính sách kế toán",en:"Standards & policies"},desc:{vi:"Lựa chọn và áp dụng nhất quán chính sách kế toán, xét đoán các ước tính trọng yếu.",en:"Choose and consistently apply policies and judge significant estimates."}},{name:{vi:"Kiểm soát nội bộ tài chính",en:"Financial controls"},desc:{vi:"Thiết kế phân quyền, phê duyệt, đối chiếu để ngăn sai sót và gian lận.",en:"Design authorities, approvals and reconciliations to prevent errors and fraud."}},{name:{vi:"Quản lý đội ngũ",en:"Team leadership"},desc:{vi:"Đào tạo, phân công và đánh giá kế toán viên, giữ tiến độ khóa sổ và báo cáo.",en:"Train, assign and assess accountants and keep close and reporting on schedule."}},{name:{vi:"Giao tiếp với bên ngoài",en:"External relations"},desc:{vi:"Giải trình với kiểm toán, ngân hàng, cơ quan thuế bằng hồ sơ và lập luận chuyên môn.",en:"Explain positions to auditors, banks and tax officers with files and sound reasoning."}},{name:{vi:"Độc lập chuyên môn",en:"Professional independence"},desc:{vi:"Từ chối ký báo cáo sai, báo cáo bằng văn bản cho cấp có thẩm quyền khi bị áp lực.",en:"Refuse to sign misstated reports and escalate in writing to the proper body under pressure."}}],knowledge:{vi:["Luật Kế toán số 88/2015/QH13 và Nghị định 174/2016/NĐ-CP: tiêu chuẩn, trách nhiệm và quyền của kế toán trưởng.","Hệ thống 26 chuẩn mực kế toán Việt Nam (VAS), trong đó VAS 23 về sự kiện phát sinh sau ngày kết thúc kỳ kế toán năm.","VAS 29 về thay đổi chính sách kế toán, ước tính kế toán và các sai sót.","Thông tư 48/2019/TT-BTC về trích lập và xử lý các khoản dự phòng.","Đề án áp dụng chuẩn mực báo cáo tài chính quốc tế IFRS tại Việt Nam (Quyết định 345/QĐ-BTC năm 2020)."],en:["Accounting Law No. 88/2015/QH13 and Decree 174/2016/ND-CP: chief accountant criteria, duties and rights.","The 26 Vietnamese Accounting Standards (VAS), including VAS 23 on events after the reporting period.","VAS 29 on changes in accounting policies, estimates and errors.","Circular 48/2019/TT-BTC on making and using provisions.","Vietnam's IFRS adoption roadmap (Decision 345/QD-BTC of 2020)."]},tools:["Phần mềm kế toán (ERP)","Hệ thống hợp nhất & lập báo cáo tài chính","Cổng thuế điện tử","Ngân hàng điện tử","Microsoft Excel"],kpis:{vi:["Báo cáo tài chính phát hành đúng hạn với ý kiến kiểm toán chấp nhận toàn phần.","Số bút toán điều chỉnh trọng yếu do kiểm toán đề xuất (mục tiêu bằng 0).","Số tiền truy thu, phạt thuế sau thanh tra, kiểm tra.","Số ngày khóa sổ tháng của toàn bộ phòng kế toán."],en:["Statements issued on time with an unmodified audit opinion.","Material audit adjustments (target zero).","Back taxes and penalties after tax audits.","Days for the whole accounting team to close the month."]},day:[{time:"08:00",vi:"Họp nhanh với đội kế toán về tiến độ khóa sổ và các vướng mắc chứng từ.",en:"Hold a quick stand-up with the team on close progress and document issues."},{time:"10:00",vi:"Duyệt đề nghị thanh toán lớn, kiểm tra hồ sơ và hạn mức phê duyệt.",en:"Approve large payment requests, checking files and approval limits."},{time:"13:30",vi:"Làm việc với kiểm toán viên về ước tính dự phòng và sự kiện sau ngày khóa sổ.",en:"Meet the auditors on provision estimates and subsequent events."},{time:"15:30",vi:"Rà soát báo cáo dòng tiền và chỉ tiêu cam kết với ngân hàng cùng giám đốc tài chính.",en:"Review cash flow and bank covenant figures with the CFO."},{time:"17:00",vi:"Ký duyệt chứng từ, cập nhật chính sách kế toán và giao việc cho ngày mai.",en:"Sign documents, update policies and assign tomorrow's tasks."}],mistakes:{vi:["Chỉ thuyết minh sự kiện sau ngày khóa sổ trong khi đó là sự kiện cần điều chỉnh số liệu.","Ký báo cáo theo áp lực lãnh đạo mà không lưu văn bản giải trình, chịu trách nhiệm cá nhân.","Thay đổi chính sách kế toán giữa kỳ để làm đẹp lợi nhuận mà không áp dụng hồi tố và thuyết minh."],en:["Only disclosing a subsequent event that actually requires adjustment.","Signing under management pressure without a written record, taking personal liability.","Changing a policy mid-year to boost profit without retrospective application and disclosure."]},career:[{vi:"Kế toán tổng hợp",en:"General accountant"},{vi:"Phó phòng kế toán",en:"Deputy chief accountant"},{vi:"Kế toán trưởng",en:"Chief accountant"},{vi:"Giám đốc tài chính (CFO)",en:"Chief Financial Officer (CFO)"}],glossary:[{term:"Sự kiện cần điều chỉnh",vi:"Sự kiện sau ngày kết thúc kỳ cung cấp bằng chứng về tình trạng đã tồn tại tại ngày kết thúc kỳ, phải sửa số liệu.",en:"Adjusting event: evidence of conditions that existed at period end, requiring figures to be changed."},{term:"Sự kiện không cần điều chỉnh",vi:"Sự kiện phản ánh tình trạng phát sinh sau ngày kết thúc kỳ, chỉ thuyết minh nếu trọng yếu.",en:"Non-adjusting event: a condition arising after period end, disclosed only if material."},{term:"Hồi tố",vi:"Điều chỉnh số liệu so sánh và số dư đầu kỳ như thể chính sách mới hoặc số đúng đã luôn được áp dụng.",en:"Retrospective restatement: adjusting comparatives and opening balances as if the correct treatment always applied."},{term:"Thư giải trình",vi:"Văn bản ban giám đốc gửi kiểm toán viên xác nhận trách nhiệm và các thông tin đã cung cấp.",en:"Management representation letter confirming responsibilities and information given to the auditor."},{term:"Covenant",vi:"Cam kết tài chính trong hợp đồng vay, ví dụ tỷ lệ nợ trên EBITDA, mà doanh nghiệp phải duy trì.",en:"A financial undertaking in a loan agreement, such as a debt to EBITDA ratio, that must be maintained."}],quiz:[{q:{vi:"Khoản phải thu 800 triệu đồng, khách nợ đã mở thủ tục phá sản, ước tính thu hồi 25%. Mức dự phòng cần trích là bao nhiêu?",en:"A VND 800 million receivable is from a debtor in bankruptcy proceedings with 25% expected recovery. What provision is needed?"},options:{vi:["200 triệu đồng","600 triệu đồng","800 triệu đồng","0 đồng"],en:["VND 200 million","VND 600 million","VND 800 million","VND 0"]},answer:1,explain:{vi:"Dự phòng bằng phần dự kiến không thu hồi: 800 x (100% - 25%) = 600 triệu đồng.",en:"Provision is the unrecoverable part: 800 x (100% - 25%) = VND 600 million."}},{q:{vi:"Sự kiện nào sau ngày kết thúc kỳ kế toán năm là sự kiện KHÔNG cần điều chỉnh?",en:"Which event after the reporting period is a NON-adjusting event?"},options:{vi:["Bản án xác nhận nghĩa vụ bồi thường đã tồn tại tại ngày khóa sổ","Phát hiện gian lận làm báo cáo năm bị sai","Bán hàng tồn kho cuối năm với giá thấp hơn giá gốc","Hỏa hoạn thiêu hủy nhà xưởng vào tháng 2 năm sau"],en:["A court ruling confirming an obligation that existed at year end","Discovery of fraud that misstated the annual figures","Selling year-end inventory below cost","A fire destroying the factory in February of the next year"]},answer:3,explain:{vi:"Hỏa hoạn là tình trạng mới phát sinh sau ngày khóa sổ, chỉ thuyết minh nếu trọng yếu; ba sự kiện còn lại là bằng chứng của tình trạng đã có.",en:"The fire is a new condition after year end, disclosed if material; the other three evidence conditions that already existed."}},{q:{vi:"Tổng giám đốc yêu cầu ký báo cáo tài chính chưa ghi nhận khoản lỗ trọng yếu và hứa tự chịu trách nhiệm. Bạn làm gì?",en:"The CEO asks you to sign statements that omit a material loss and promises to take responsibility. What do you do?"},options:{vi:["Từ chối ký, giải trình bằng văn bản và báo chủ sở hữu hoặc Hội đồng quản trị","Ký vì đã có cam kết của tổng giám đốc","Ký nhưng ghi chú riêng trong sổ tay","Nghỉ phép để người khác ký thay"],en:["Refuse to sign, explain in writing and report to the owner or the Board","Sign because the CEO made a commitment","Sign but keep a private note","Take leave so someone else signs"]},answer:0,explain:{vi:"Kế toán trưởng độc lập về chuyên môn và chịu trách nhiệm về số liệu; cam kết miệng không miễn trách nhiệm.",en:"The chief accountant is professionally independent and answerable for the figures; a verbal promise removes no liability."}},{q:{vi:"Phát hiện sai sót trọng yếu của năm trước. Theo VAS 29, cách xử lý đúng là gì?",en:"A material prior-year error is found. Under VAS 29, what is the right treatment?"},options:{vi:["Ghi toàn bộ vào chi phí năm nay","Bỏ qua vì năm trước đã quyết toán","Điều chỉnh hồi tố số liệu so sánh và số dư đầu kỳ","Chỉ thông báo miệng cho kiểm toán viên"],en:["Expense it all this year","Ignore it since last year is closed","Restate comparatives and opening balances retrospectively","Only tell the auditor verbally"]},answer:2,explain:{vi:"Sai sót trọng yếu kỳ trước phải được điều chỉnh hồi tố và thuyết minh, không ghi vào kết quả kỳ hiện tại.",en:"Material prior-period errors are corrected retrospectively and disclosed, not through current profit."}}],tools_en:["Accounting software (ERP)","Financial consolidation & reporting system","E-tax portal","Online banking","Microsoft Excel"]}}})})(window.KKR);
